const infolensThemeParams=new URLSearchParams(location.search);const applyInfolensTheme=(theme)=>document.documentElement.dataset.theme=theme==="dark"?"dark":"light";applyInfolensTheme(infolensThemeParams.get("theme"));addEventListener("message",(event)=>{if(event.data?.type==="infolens:theme")applyInfolensTheme(event.data.theme)});const api=new URLSearchParams(location.search).get("apiBaseUrl");const $=(selector)=>document.querySelector(selector);let data;
async function request(route,options){const response=await fetch(new URL(route,api),options);if(!response.ok)throw new Error(`Plugin API returned ${response.status}`);return response.json()}
function productRow(product){const li=document.createElement("li");li.className=`product${product.read?" is-read":""}`;const rank=document.createElement("span");rank.className="rank";rank.textContent=String(product.rank).padStart(2,"0");const content=document.createElement("button");content.className="product-link";content.innerHTML=`<strong></strong><span>producthunt.com</span>`;content.querySelector("strong").textContent=product.name;content.onclick=async()=>{window.open(product.url,"_blank","noopener");data=await request(`read?url=${encodeURIComponent(product.url)}`,{method:"POST"});render(data)};const votes=document.createElement("span");votes.className="votes";votes.textContent=`▲ ${product.votes}`;li.append(rank,content,votes);return li}
function render(next){data=next;const products=next.products??[];const disconnected=next.dependencyState==="disconnected";$("#dependency").hidden=!disconnected;document.querySelector("main").hidden=disconnected&&!products.length;$("#products").replaceChildren(...products.map(productRow));$("#products").hidden=!products.length;$("#empty").hidden=Boolean(products.length);$("#warning").hidden=!next.lastError||disconnected;const date=next.lastSuccessfulRefresh&&new Date(next.lastSuccessfulRefresh);$("#refresh-time").textContent=date?`Updated ${new Intl.DateTimeFormat("en",{month:"short",day:"numeric",hour:"2-digit",minute:"2-digit"}).format(date)}`:"Not refreshed yet";$("#refresh").disabled=next.settings?.policy==="disabled"}
async function load(){if(!api)throw new Error("Missing plugin API configuration");render(await request("summary"))}
async function refresh(){const button=$("#refresh");button.disabled=true;button.classList.add("spinning");$("#refresh-time").textContent="Queued for refresh...";try{await request("refresh",{method:"POST"});render(await request("summary"))}catch(error){const latest=await request("summary").catch(()=>data);render({...latest,lastError:latest?.lastError??error.message})}finally{button.classList.remove("spinning");button.disabled=data?.settings?.policy==="disabled"}}
function showSettings(show){$("#sheet").hidden=!show;$("#scrim").hidden=!show;if(show){document.querySelector(`[name=policy][value=${data.settings.policy}]`).checked=true;$("#interval").value=data.settings.intervalMinutes;$("#interval").disabled=data.settings.policy!=="fixed"}else $("#settings").focus()}
$("#refresh").onclick=$("#retry").onclick=$("#empty-refresh").onclick=$("#dependency-retry").onclick=refresh;$("#settings").onclick=()=>showSettings(true);$("#close-settings").onclick=$("#cancel-settings").onclick=$("#scrim").onclick=()=>showSettings(false);document.querySelectorAll("[name=policy]").forEach((radio)=>radio.onchange=()=>$("#interval").disabled=radio.value!=="fixed");$("#settings-form").onsubmit=async(event)=>{event.preventDefault();const form=new FormData(event.currentTarget);await request(`settings?policy=${form.get("policy")}&intervalMinutes=${form.get("intervalMinutes")}`,{method:"POST"});render(await request("summary"));showSettings(false)};addEventListener("keydown",(event)=>{if(event.key==="Escape"&&!$("#sheet").hidden)showSettings(false)});load().catch((error)=>$("#products").innerHTML=`<li class="loading">${error.message}</li>`);
